def skill():
    a = Symbol('a', positive=True)
    sol = solve(20 + 2*a**3 - 36, a)
    assert len(sol) == 1
    x = Symbol('x')
    return (x**3 - 3*sol[0]**2*x + 20).subs(x, 3)

def standard():
    a, t, x = symbols('a t x', real=True)
    f = x**3 - 3*a**2*x + 20
    sols = solve([f.subs(x, t) - 36, diff(f, x).subs(x, t)], [a, t], dict=True)
    sols = [s for s in sols if s[a] > 0]
    assert len(sols) == 1
    return f.subs(a, sols[0][a]).subs(x, 3)

def unique():
    return [standard()]
